#include <cstdio>
#include <cstdlib>
#include <cuda_runtime.h>
#define TILE 16

__global__ void matmul(const float* A, const float* B, float* C, int N) {
  __shared__ float As[TILE][TILE], Bs[TILE][TILE];
  int r = blockIdx.y * TILE + threadIdx.y, c = blockIdx.x * TILE + threadIdx.x;
  float s = 0;
  for (int t = 0; t < N / TILE; t++) {
    As[threadIdx.y][threadIdx.x] = A[r * N + t * TILE + threadIdx.x];
    Bs[threadIdx.y][threadIdx.x] = B[(t * TILE + threadIdx.y) * N + c];
    __syncthreads();
    for (int k = 0; k < TILE; k++) s += As[threadIdx.y][k] * Bs[k][threadIdx.x];
    __syncthreads();
  }
  C[r * N + c] = s;
}

int main() {
  int N = 64;
  size_t bytes = N * N * sizeof(float);
  float *hA = (float*)malloc(bytes), *hB = (float*)malloc(bytes), *hC = (float*)malloc(bytes);
  for (int i = 0; i < N * N; i++) { hA[i] = 1.0f; hB[i] = 1.0f; }
  float *dA, *dB, *dC;
  cudaMalloc(&dA, bytes); cudaMalloc(&dB, bytes); cudaMalloc(&dC, bytes);
  cudaMemcpy(dA, hA, bytes, cudaMemcpyHostToDevice);
  cudaMemcpy(dB, hB, bytes, cudaMemcpyHostToDevice);
  dim3 block(TILE, TILE), grid(N / TILE, N / TILE);
  matmul<<<grid, block>>>(dA, dB, dC, N);
  cudaMemcpy(hC, dC, bytes, cudaMemcpyDeviceToHost);
  printf("C[0]=%.0f\n", hC[0]);  // 64
  cudaFree(dA); cudaFree(dB); cudaFree(dC);
  free(hA); free(hB); free(hC);
  return 0;
}

#include <cstdio>
#include <cstdlib>
#include <cuda_runtime.h>
#define T 256

__global__ void reduce(const float* x, float* out, int n) {
  __shared__ float s[T];
  int i = blockIdx.x * blockDim.x + threadIdx.x, t = threadIdx.x;
  s[t] = (i < n) ? x[i] : 0.0f;
  __syncthreads();
  for (int d = blockDim.x / 2; d > 0; d >>= 1) {
    if (t < d) s[t] += s[t + d];
    __syncthreads();
  }
  if (t == 0) atomicAdd(out, s[0]);
}

int main() {
  int n = 1 << 20;
  size_t bytes = n * sizeof(float);
  float* hx = (float*)malloc(bytes);
  for (int i = 0; i < n; i++) hx[i] = 1.0f;
  float *dx, *dout;
  cudaMalloc(&dx, bytes); cudaMalloc(&dout, sizeof(float));
  cudaMemset(dout, 0, sizeof(float));
  cudaMemcpy(dx, hx, bytes, cudaMemcpyHostToDevice);
  reduce<<<(n + T - 1) / T, T>>>(dx, dout, n);
  float sum = 0;
  cudaMemcpy(&sum, dout, sizeof(float), cudaMemcpyDeviceToHost);
  printf("sum=%.0f\n", sum);  // 1048576
  cudaFree(dx); cudaFree(dout); free(hx);
  return 0;
}

