int main() {
  int n = 1 << 20;
  size_t bytes = n * sizeof(float);
  float* h;
  cudaMallocHost(&h, bytes);          // pinned host memory enables async copies
  for (int i = 0; i < n; i++) h[i] = 1.0f;
  float* d;
  cudaMalloc(&d, bytes);
  cudaStream_t s;
  cudaStreamCreate(&s);
  int T = 256;
  cudaMemcpyAsync(d, h, bytes, cudaMemcpyHostToDevice, s);
  scale<<<(n + T - 1) / T, T, 0, s>>>(d, n, 2.0f);
  cudaMemcpyAsync(h, d, bytes, cudaMemcpyDeviceToHost, s);
  cudaStreamSynchronize(s);
  printf("h[0]=%.1f\n", h[0]);  // 2.0
  cudaStreamDestroy(s); cudaFree(d); cudaFreeHost(h);
  return 0;
}

#include <cstdio>
#include <thrust/device_vector.h>
#include <thrust/transform.h>
#include <thrust/reduce.h>
#include <thrust/functional.h>

// Thrust ships with the CUDA Toolkit and provides tested, tuned parallel
// primitives, so you rarely hand-write a kernel for standard map/reduce work.
int main() {
    const int n = 1 << 20;
    thrust::device_vector<float> x(n, 1.0f);   // n ones, allocated in device memory
    thrust::device_vector<float> y(n, 2.0f);
    thrust::device_vector<float> z(n);

    // z = x + y, element-wise -- a tuned library kernel, no custom code
    thrust::transform(x.begin(), x.end(), y.begin(), z.begin(), thrust::plus<float>());

    // parallel reduction, also from the library
    float total = thrust::reduce(z.begin(), z.end(), 0.0f, thrust::plus<float>());
    printf("sum of z = %.0f (expected %d)\n", total, 3 * n);   // 3 * 2^20 = 3145728
    return 0;
}

#include <cstdio>
#include <cuda_runtime.h>

__global__ void addScalar(float* a, int n, float s) {
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n; i += blockDim.x * gridDim.x)
        a[i] += s;
}

int main() {
    int devices = 0;
    cudaGetDeviceCount(&devices);
    printf("found %d GPU(s)\n", devices);
    if (devices < 1) return 0;

    const int n = 1 << 20;
    const int chunk = (n + devices - 1) / devices;   // split the array across GPUs
    size_t bytes = (size_t)n * sizeof(float);
    float* h = (float*)malloc(bytes);
    for (int i = 0; i < n; i++) h[i] = 1.0f;

    for (int d = 0; d < devices; d++) {
        cudaSetDevice(d);                            // all later calls target GPU d
        int start = d * chunk;
        int len = (start + chunk <= n) ? chunk : n - start;
        if (len <= 0) continue;
        float* dptr;
        cudaMalloc(&dptr, (size_t)len * sizeof(float));
        cudaMemcpy(dptr, h + start, (size_t)len * sizeof(float), cudaMemcpyHostToDevice);
        int T = 256;
        addScalar<<<(len + T - 1) / T, T>>>(dptr, len, (float)(d + 1));   // GPU d adds d+1
        cudaMemcpy(h + start, dptr, (size_t)len * sizeof(float), cudaMemcpyDeviceToHost);
        cudaFree(dptr);
    }
    for (int d = 0; d < devices; d++) { cudaSetDevice(d); cudaDeviceSynchronize(); }
    printf("h[0]=%.0f h[n-1]=%.0f\n", h[0], h[n - 1]);   // slice 0 -> 2, last slice -> 1+devices
    free(h);
    return 0;
}

#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <cuda_runtime.h>

__global__ void saxpy(int n, float a, const float* x, float* y) {
  for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n; i += blockDim.x * gridDim.x)
    y[i] = a * x[i] + y[i];
}

int main() {
  int n = 1 << 20;
  size_t bytes = n * sizeof(float);
  float *hx = (float*)malloc(bytes), *hy = (float*)malloc(bytes);
  for (int i = 0; i < n; i++) { hx[i] = 1.0f; hy[i] = 2.0f; }
  float *dx, *dy;
  cudaMalloc(&dx, bytes); cudaMalloc(&dy, bytes);
  cudaMemcpy(dx, hx, bytes, cudaMemcpyHostToDevice);
  cudaMemcpy(dy, hy, bytes, cudaMemcpyHostToDevice);
  cudaEvent_t start, stop;
  cudaEventCreate(&start); cudaEventCreate(&stop);
  int T = 256;
  cudaEventRecord(start);
  saxpy<<<(n + T - 1) / T, T>>>(n, 3.0f, dx, dy);
  cudaEventRecord(stop);
  cudaEventSynchronize(stop);
  float ms = 0;
  cudaEventElapsedTime(&ms, start, stop);
  cudaMemcpy(hy, dy, bytes, cudaMemcpyDeviceToHost);
  float maxErr = 0;
  for (int i = 0; i < n; i++) maxErr = fmaxf(maxErr, fabsf(hy[i] - 5.0f));  // 3*1+2
  printf("max error %.1f in %.3f ms\n", maxErr, ms);
  cudaFree(dx); cudaFree(dy); free(hx); free(hy);
  return 0;
}
